		private void OnClicked(in global::UnityEngine.Vector2 inPos) {
			if (gameState != GameState.Dig)
				return;
			int crumblingNum = crumblingEffectNum[CalcIndex(digGaugeMax, crumblingEffectNum.Count - 1)];
			for (int i = 0; i < crumblingNum; i++)
			{
				if (i == 0)
					effectManager.PlayToCrumbling((int)(inPos.x / board.GridSize.x));
				else
					effectManager.PlayToCrumbling(-1, UnityEngine.Random.Range(0.0f, 0.5f));
			}
			int shakeIndex = CalcIndex(digGaugeMax, cameraShakeStrength.Count - 1);
			cameraShaker?.DoShake(cameraShakeStrength[shakeIndex], 0.2f);
			digGauge -= (1.0f - tonariModeGaugeDownCorrection * digParam.NumOfOtherParticipants) * (toolSwitch.IsPickaxe ? COST_DIG_PIC : COST_DIG_HUMMER);
			if (digGauge <= 0.0f)
				digGauge = 0.0f;
			board.Dig(inPos, toolSwitch.IsPickaxe);
			buildupViewManager.ApplyDurability(board.BuildupMap);
			SendDigData(inPos, !toolSwitch.IsPickaxe);
			gauge.SetGauge(digGauge);
			effectManager.PlayToCrack(1.0f - digGauge / digGaugeMax);
			if (board.IsCheckDigOutAll() || digGauge == 0.0f)
			{
				cursor.SetDisplay(false);
				CloseKeyguide();
				SetState(GameState.EndDirection);
			}

			int CalcIndex(float maxValue, int count)
			{
				return Mathf.Clamp((int)(count / (maxValue / (maxValue - digGauge))), 0, count);
			}
        }
