		private global::System.Collections.IEnumerator ResultDirection() {
			bool bIsDigOutAllItems = board.IsCheckDigOutAll();
			audioManager.StopDelaySeAll();
			if (bIsDigOutAllItems)
			{
				yield return new UnityEngine.WaitForSeconds(waitingTimeToDigOutAllItemsResult);
			}
			else
			{
				cameraShaker.DoShake(1.0f, cameraShakeDuration);
				vibration.CollapsePhase1(toResultBlackOut.x);
				for (int i = 0; i < 10; i++)
					effectManager.PlayToCrumbling(-1, UnityEngine.Random.Range(0.0f, 1.3f));
				yield return new UnityEngine.WaitForSeconds(toResultBlackOut.x);
				vibration.CollapsePhase2(1.0f);
				directionEffectInstance = effectManager.PlayToCollapse();
				audioManager.PlaySe(DigAudioManager.SeId.CollapseWall);
				bool isResultDirectionDone = false;
				// one Color.black read (@0198d164) feeds both colours: alpha 0 -> alpha 1
				Color startColor = Color.black;
				startColor.a = 0.0f;
				Color endColor = startColor;
				endColor.a = 1.0f;
				fade.FadeStart(DigFade.Type.OverUI, startColor, endColor, toResultBlackOut.y, () =>
				{
					directionEffectInstance.Stop(0.0f, true);
					isResultDirectionDone = true;
				});
				while (!isResultDirectionDone)
					yield return null;
				yield return new UnityEngine.WaitForSeconds(0.2f);
			}
			message.ShowResultMessage(bIsDigOutAllItems, () => SetState(GameState.MessageWait), () => SetState(GameState.ResultCommonItem));
			if (bIsDigOutAllItems)
				audioManager.PlaySe(DigAudioManager.SeId.DigOutAllItems);
		}
