		private void SetUIAndCamera(global::Dpr.DigFossil.DigCameraManager.CameraSet set) {
			cameraManager.SetCamera(set);
			switch (set)
			{
				case DigCameraManager.CameraSet.Game:
					UIRoot.SetActive(true);
					fallBoradDirection.SetActive(false);
					resultBg.SetActive(false);
					break;
				case DigCameraManager.CameraSet.ItemResult:
					UIRoot.SetActive(false);
					resultBg.SetActive(true);
					fallBoradDirection.SetActive(false);
					break;
				case DigCameraManager.CameraSet.BoxResult:
					UIRoot.SetActive(false);
					resultBg.SetActive(false);
					fallBoradDirection.SetActive(false);
					break;
			}
		}
