		private void ExitDigFossil(bool isDig) {
			PlayerWork.isDigFossil = false;
			if (isDig)
			{
				if (!FlagWork.GetSysFlag(Dpr.EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_UG_DIG))
					FlagWork.SetSysFlag(Dpr.EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_UG_DIG, true);
				if (!FlagWork.GetSysFlag(Dpr.EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_UG_FRIEND_KASEKIHORI_SUCCESS) && !isHost)
					FlagWork.SetSysFlag(Dpr.EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_UG_FRIEND_KASEKIHORI_SUCCESS, true);
			}
			PlayerWork.UgCountRecord.IncrementDigFossilPlayCount();
			if (DigWork.isFromDebugMenu)
			{
				StartCoroutine(GameInitialize());
				StartCoroutine(ShowStartMessage());
			}
			else
			{
				Audio.AudioManager.Instance.SetBgmEvent("DuckOff_BGM", false);
				PlayerWork.SetTransitionZone(PlayerWork.zoneID, -1);
			}
			SaveReport();
		}
		private void SaveReport() {
			uint[] digItemNumbers = board.GetDigItemNumbers();
			uint connection = UgNetworkManager.connectType == INL1.IlcaNetSessionNetworkType.Local ? 1u
				: UgNetworkManager.connectType == INL1.IlcaNetSessionNetworkType.Internet ? 2u : 0u;
			PlayReportManager.SaveReportLog_FossilDigging(connection, !isHost, digItemNumbers, (uint)digItemNumbers.Length);
		}
