		private void OnReceiveDigFossileNetData(global::Dpr.NetworkUtils.INetData data) {
			if (NetDigAttackData.DataID == data.GetDataID)
				TonariDigAttack(data as NetDigAttackData);
			if (NetDigEndData.DataID == data.GetDataID)
				HostEnd();
			if (NetDigJoinMemberCount.DataID == data.GetDataID)
			{
				int otherParticipants = (data as NetDigJoinMemberCount).data.Value - 1;
				if (digParam.NumOfOtherParticipants < otherParticipants)
					digParam.NumOfOtherParticipants = otherParticipants;
			}
		}
		private void HostEnd() { }
		private bool AddCursor(int stationIndex) {
			if (!isHost)
				return false;
			DigCursor tonariCursor = tonariCursorList.Find(x => !x.IsUse);
			if (tonariCursor == null)
				return false;
			tonariCursor.IsUse = true;
			tonariCursorDic.Add(stationIndex, tonariCursor);
			effectManager.AddCursor(stationIndex, tonariCursor.effectRoot);
			tonariCursor.SetActive(true);
			tonariCursor.Initialize();
			return true;
		}
		private void TonariDigAttack(global::Dpr.NetworkUtils.NetDigAttackData data) {
			if (gameState != GameState.Dig)
				return;
			if (!isHost || data == null)
				return;
			if (!tonariCursorDic.ContainsKey(data.FromStationIndex) && AddCursor(data.FromStationIndex))
				return;
			tonariCursorDic[data.FromStationIndex].DigPosition(data.data.position, !data.data.isHammer);
			board.Dig(data.data.position, !data.data.isHammer, false, data.FromStationIndex);
			buildupViewManager.ApplyDurability(board.BuildupMap);
		}
		public DigFossilController() { }
		public class DigParam
		{
			public int NumOfOtherParticipants;
			public float DropUpCorrection;
			public float Bonus { get { return DropUpCorrection * NumOfOtherParticipants + 1f; } }
			public DigParam() { }
		}
		private enum GameState
		{
			Init = 0,
			FadeIn = 1,
			FirstEvent = 2,
			StartMessageShow = 3,
			Dig = 4,
			EndDirection = 5,
			EndMessageShow = 6,
			ResultCommonItem = 7,
			ResultCommonItemWait = 8,
			ResultStoneBox = 9,
			MessageWait = 10,
			MessageCloseWait = 11,
		}
	}
}
